+__device__ __forceinline__ float round_to_nearest_e2m1(float x) {
+  const float ax = fabsf(x);
+  float q;
+  // Match cvt.rn.satfinite.e2m1x2.f32, including ties-to-even boundaries.
+  if (ax <= 0.25f) {
+    q = 0.0f;
+  } else if (ax < 0.75f) {
+    q = 0.5f;
+  } else if (ax <= 1.25f) {
+    q = 1.0f;
+  } else if (ax < 1.75f) {
+    q = 1.5f;
+  } else if (ax <= 2.5f) {
+    q = 2.0f;
+  } else if (ax < 3.5f) {
+    q = 3.0f;
+  } else if (ax <= 5.0f) {
+    q = 4.0f;
+  } else {
+    q = 6.0f;
+  }
+  return copysignf(q, x);
+}
